:root {
  --primary: #2f49ff;
  --primary-dark: #1d32cc;
  --accent: #14d68f;
  --accent-coral: #ff6f61;
  --bg: #ffffff;
  --bg-soft: #f6f8ff;
  --text: #14182b;
  --muted: #5d6785;
  --card: #ffffff;
