html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Plus Jakarta Sans", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
}
a { color: inherit; text-decoration: none; }
.container { width: min(1140px, 92%); margin: 0 auto; }
.navbar {
  position: sticky; top: 0; z-index: 50;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid #e8ebff;
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; gap: 12px; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; letter-spacing: .2px; }
.brand-badge {
  width: 34px; height: 34px; border-radius: 11px;
  display: grid; place-items: center; color: #fff;
  background: linear-gradient(135deg, var(--primary), #5d71ff);
}
.nav-links { display: flex; gap: 18px; flex-wrap: wrap; color: #2e3657; font-weight: 600; font-size: 14px; }
.nav-links a { padding: 8px 10px; border-radius: 10px; }
.nav-links a:hover, .nav-links a.active { background: #eef1ff; color: var(--primary-dark); }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  border: 0; border-radius: 12px; padding: 12px 18px;
  font-weight: 700; cursor: pointer; transition: transform .25s ease, box-shadow .25s ease, background .25s ease;
}
.btn-primary { background: linear-gradient(135deg, var(--primary), #5a70ff); color: #fff; box-shadow: var(--shadow); }
.btn-primary:hover { transform: translateY(-2px); }
.btn-ghost { background: #edf1ff; color: var(--primary-dark); }
.hero { padding: 72px 0 34px; }
.hero-grid { display: grid; grid-template-columns: 1.02fr .98fr; gap: 30px; align-items: center; }
.kicker { color: var(--primary); font-size: 13px; letter-spacing: .16em; text-transform: uppercase; font-weight: 800; }
h1 { font-size: clamp(2rem, 4.6vw, 3.4rem); line-height: 1.1; margin: 10px 0 16px; }
.lead { color: var(--muted); font-size: 1.07rem; margin-bottom: 24px; }
.hero-cta { display: flex; gap: 10px; flex-wrap: wrap; }
.mock {
  background: linear-gradient(160deg, #f4f7ff, #ebf4ff 55%, #efffff);
  border: 1px solid #dfe6ff; border-radius: 22px; box-shadow: var(--shadow);
  overflow: hidden;
}
.mock-tabs { display: inline-flex; background: #e7ecff; padding: 4px; border-radius: 12px; margin-bottom: 12px; }
.mock-tab { border: 0; border-radius: 10px; padding: 9px 13px; font-weight: 700; background: transparent; color: #43507a; cursor: pointer; }
.mock-tab.active { background: #fff; color: var(--primary-dark); box-shadow: 0 4px 14px rgba(30,41,98,.16); }
.view-panel { display: none; }
.view-panel.active { display: block; animation: fadeIn .4s ease; }
.preview { padding: 16px; }
.preview h4 { margin: 2px 0 6px; }
.preview p { margin: 0; color: var(--muted); font-size: 14px; }
.preview-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 10px; margin-top: 12px; }
.preview-card { background: #fff; border: 1px solid #e3e9ff; border-radius: 12px; padding: 10px; }
.stats { background: linear-gradient(135deg, #1e2ec9, #2f49ff 55%, #3f75ff); color: #fff; margin-top: 16px; }
.stats-inner { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; padding: 22px 0; }
.stat { text-align: center; }
.stat strong { display: block; font-size: clamp(1.4rem,3vw,2.2rem); }
.stat span { color: #d9e0ff; font-size: 14px; }
.section { padding: 68px 0; }
.section.alt { background: var(--bg-soft); }
.section h2 { margin: 0 0 12px; font-size: clamp(1.55rem,3.2vw,2.5rem); }
.section-sub { color: var(--muted); margin-bottom: 24px; max-width: 760px; }
.grid-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 16px; }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.card { background: var(--card); border: 1px solid #e5e9ff; border-radius: var(--radius); padding: 20px; box-shadow: 0 6px 18px rgba(31,50,154,.06); }
.card h3, .card h4 { margin: 0 0 8px; }
.card p { margin: 0; color: var(--muted); }
.why-tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 16px; }
.why-tab { border: 1px solid #d7defe; background: #fff; color: #44507a; font-weight: 700; border-radius: 12px; padding: 10px 12px; cursor: pointer; }
.why-tab.active { background: #eaf0ff; color: var(--primary-dark); border-color: #c8d4ff; }
.why-panel { display: none; }
.why-panel.active { display: block; animation: fadeIn .35s ease; }
.why-list { margin: 12px 0 0; padding-left: 20px; color: var(--muted); }
.integrations { display: grid; grid-template-columns: repeat(6,1fr); gap: 12px; }
.logo { border: 1px solid #dde5ff; border-radius: 14px; padding: 16px 10px; text-align: center; font-weight: 700; color: #33406f; background: #fff; }
.carousel { position: relative; }
.carousel-track { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; }
.testi { border-left: 4px solid var(--accent); }
.testi em { color: #3a4366; font-style: normal; font-weight: 600; }
.carousel-controls { margin-top: 12px; display: flex; gap: 8px; }
.carousel-btn { border: 1px solid #cfd9ff; background: #fff; border-radius: 10px; padding: 8px 11px; cursor: pointer; }
.faq { display: grid; gap: 10px; }
.faq-item { border: 1px solid #dce4ff; border-radius: 14px; overflow: hidden; background: #fff; }
.faq-question { width: 100%; border: 0; background: #fff; text-align: left; padding: 15px 16px; font-weight: 700; color: #25315d; cursor: pointer; }
.faq-answer { display: none; padding: 0 16px 15px; color: var(--muted); }
.faq-item.active .faq-answer { display: block; }
.pricing { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.price { font-size: 2rem; font-weight: 800; margin: 12px 0 8px; }
.price small { font-size: 14px; color: var(--muted); font-weight: 600; }
.list { padding-left: 18px; color: var(--muted); }
.cta-band { background: linear-gradient(135deg, #1d32cc, #2f49ff); color: #fff; border-radius: 24px; padding: 28px; display: flex; justify-content: space-between; align-items: center; gap: 14px; }
.footer { background: #101633; color: #c9d2ff; padding: 28px 0; margin-top: 48px; }
.footer a { color: #fff; }
.demo-toggle { width: 100%; text-align: left; border: 1px solid #dce5ff; background: #fff; border-radius: 14px; padding: 14px; font-weight: 700; cursor: pointer; }
.demo-content { display: none; margin-top: 10px; }
.demo-content.active { display: block; }
.reveal { opacity: 0; transform: translateY(18px); transition: .6s ease; }
.reveal.in { opacity: 1; transform: translateY(0); }
@keyframes fadeIn { from {opacity: 0; transform: translateY(8px);} to {opacity:1; transform: translateY(0);} }
@media (max-width: 980px) {
  .hero-grid, .grid-4, .grid-3, .pricing, .integrations, .carousel-track, .stats-inner { grid-template-columns: 1fr 1fr; }
  .nav-inner { flex-wrap: wrap; }
}
@media (max-width: 680px) {
  .hero-grid, .grid-4, .grid-3, .pricing, .integrations, .carousel-track, .stats-inner { grid-template-columns: 1fr; }
  .cta-band { flex-direction: column; align-items: flex-start; }
}
EOF

cat > /app/output/app.js <<'EOF'
document.querySelectorAll('.mock-tab').forEach((tab) => {
  tab.addEventListener('click', () => {
    const wrap = tab.closest('[data-tab-wrap]');
    wrap.querySelectorAll('.mock-tab').forEach((t) => t.classList.remove('active'));
    tab.classList.add('active');
    const key = tab.dataset.tab;
    wrap.querySelectorAll('.view-panel').forEach((p) => p.classList.toggle('active', p.dataset.view === key));
  });
});

document.querySelectorAll('[data-why-tabs]').forEach((wrap) => {
  const tabs = wrap.querySelectorAll('.why-tab');
  const panels = wrap.querySelectorAll('.why-panel');
  tabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      tabs.forEach((t) => t.classList.remove('active'));
      tab.classList.add('active');
      const panel = tab.dataset.panel;
      panels.forEach((p) => p.classList.toggle('active', p.dataset.panel === panel));
    });
  });
});

document.querySelectorAll('.faq').forEach((faq) => {
  faq.querySelectorAll('.faq-question').forEach((btn) => {
    btn.addEventListener('click', () => {
      faq.querySelectorAll('.faq-item').forEach((item) => item.classList.remove('active'));
      btn.closest('.faq-item').classList.add('active');
    });
  });
});

document.querySelectorAll('[data-carousel]').forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll('[data-item]'));
  let page = 0;
  const per = 3;
  const render = () => {
    items.forEach((item, i) => {
      const start = page * per;
      item.style.display = i >= start && i < start + per ? 'block' : 'none';
    });
  };
  carousel.querySelector('.carousel-prev')?.addEventListener('click', () => {
    page = page <= 0 ? Math.ceil(items.length / per) - 1 : page - 1;
    render();
  });
  carousel.querySelector('.carousel-next')?.addEventListener('click', () => {
    page = page >= Math.ceil(items.length / per) - 1 ? 0 : page + 1;
    render();
  });
  render();
});

document.querySelectorAll('[data-demo-toggle]').forEach((btn) => {
  btn.addEventListener('click', () => {
    const target = document.getElementById(btn.dataset.demoToggle);
    target.classList.toggle('active');
  });
});

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) entry.target.classList.add('in');
  });
}, { threshold: 0.14 });
document.querySelectorAll('.reveal').forEach((el) => observer.observe(el));
EOF

